    def verify_alarm(self, **kwargs):
        """
        *Description:* \n
       This keyword verifies the alarm based on given arguments.

        *Steps Followed* \n
             a. Gets the list of alarms \n
             b. Verifies the fetched alarms as per parameters passed \n
             c. Raises following exceptions \n
                AllAlarmOccurencesNotFoundException - If expected occurrence is more than actual
                \nAlarmNotFoundException - If found/actual occurrence is zero. \n
                AlarmShouldNotExistException - If should_exist is expected to be False
                                               but alarm occurrences are not zero

        *Parameters:* \n

        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |
        | enb_id | None | The eNB ID |  |
        | faultid | Mandatory | (int) The fault id to look for | |
        |  |  | For netact: faultid is mandatory if alarmid is not passed  |  |
        | should_exist | True | If True, checks for alarm's existence | |
        | occurrences | 1 | If the alarm should exist, how many occurences are expected | |


        *Returns* \n
        Active alarms

        *Raises Exceptions*
        | *Exception* | *Triggering Event* |
        | AllAlarmOccurencesNotFoundException | If expected occurrences are not found |
        | AlarmNotFoundException | If found/actual occurrence is zero |
        | AlarmShouldNotExistException | If should_exist is expected to be False  but alarm occurrences are not zero |
        | AlarmIdOrFaultIdOnlyException | Either alarmid or faultid must be passed, not both. |

        *Example:* \n
        | Verify Ems Alarm | config_device=emssim2 | alarmid=41003 |  should_exist=${True} | occurrences=1 | alias=alias |

        """
        return EmsSim().verify_alarm(**kwargs)

    def configuration_manage(self, **kwargs):
        """
        *Description:* \n
        This keyword is used to perform configuration management.

        *Steps Followed* \n
             a. Uploads configuration data \n
             b. Creates plan and adds/edits moc parameter to plan \n
             c. Provisions the plan

        *Parameters:* \n

        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |
        | operation | Mandatory | Create or Edit or Delete or Deconfigure. Valid on EMS interface only | delta_files  |
        |  |  | Operation argument is valid only for EMS. It will become dummy when the keyword is called over netact |  |
        |  |  | interface |  |
        | config | Mandatory for operation create or edit | XML file, or YAML file or The configuration string |  |
        |  |  | structure with list of dict or dict |  |
        | operation | Mandatory | Create or Edit or Delete or Deconfigure | delta_files |
        | skip_ro | True | skip Read-Only attributes (does not raise an error on RO attribute modification) |  |
        | skip_np | True | skip not present attributes, i.e. marked in NIDD as Hidden or Not Used |  |
        | wait | 60 |  In seconds, waits for BTS restart. Used incase of Create or Edit Operation |  |
        | wait_on_air | True | In seconds, Waits for BTS to come onAir. Used incase of Create or Edit Operation |  |
        | del_obj_name | Mandatory for operation delete | Deletes the given object |  |
        | strict | False | If True throws an error if object does not exist. Used for operation delete |  |
        | enb_id | None | The eNB ID |  |
        | alias | default | Name of execution context. | |

        *Returns*:
        None

        *Raises*:

       """
        return EmsSim().configuration_manage(**kwargs)

